12: // Helper: Cosine Similarity
13: function cosineSimilarity(vecA, vecB) {
14:   let dotProduct = 0;
15:   let normA = 0;
16:   let normB = 0;
17:   for (let i = 0; i < vecA.length; i++) {
18:     dotProduct += vecA[i] * vecB[i];
19:     normA += vecA[i] * vecA[i];
20:     normB += vecB[i] * vecB[i];
21:   }
22:   if (normA === 0 || normB === 0) return 0;
23:   return dotProduct / (Math.sqrt(normA) * Math.sqrt(normB));
24: }
25: 
26: // Helper: Split text into chunks
27: function chunkText(text, chunkSize = 1500, overlap = 200) {
28:   const chunks = [];
29:   let i = 0;
30:   while (i < text.length) {
31:     const chunk = text.slice(i, i + chunkSize);
32:     chunks.push(chunk);
33:     i += chunkSize - overlap;
34:   }
35:   return chunks;
36: }
