38: /**
39:  * Initialize RAG: Extract PDF texts, chunk them, and create embeddings.
40:  */
41: async function initializeRAG(pdfDirPath, genAI) {
42:   embeddingModel = genAI.getGenerativeModel({ model: "gemini-embedding-001" });
43:   
44:   // Try loading from cache first
45:   if (fs.existsSync(CACHE_FILE)) {
46:     console.log("Loading RAG embeddings from cache...");
47:     try {
48:       const rawCache = fs.readFileSync(CACHE_FILE, 'utf-8');
49:       vectorStore = JSON.parse(rawCache);
50:       if (vectorStore.length > 0) {
51:         console.log(`Loaded ${vectorStore.length} chunks from cache.`);
52:         return;
53:       } else {
54:         console.log("Cache is empty, regenerating embeddings...");
55:       }
56:     } catch (e) {
57:       console.log("Cache reading failed, regenerating embeddings...");
58:     }
59:   }
60: 
61:   console.log("Extracting texts from PDFs...");
62:   const { text, count } = await extractTextFromFolder(pdfDirPath);
63:   
64:   if (count === 0 || text.trim().length === 0) {
65:     console.log("No PDF text found. Skipping RAG init.");
66:     return;
67:   }
68: 
69:   console.log(`Chunking text... (Total length: ${text.length} chars)`);
70:   const chunks = chunkText(text);
71:   console.log(`Generated ${chunks.length} chunks. Creating embeddings (this may take a moment)...`);
72: 
73:   // Create embeddings in batches to avoid rate limits and quota exhaustion
74:   const BATCH_SIZE = 50;
75:   for (let i = 0; i < chunks.length; i += BATCH_SIZE) {
76:     const batchChunks = chunks.slice(i, i + BATCH_SIZE);
77:     try {
78:       const requests = batchChunks.map(chunk => ({ content: { parts: [{ text: chunk }] } }));
79:       const result = await embeddingModel.batchEmbedContents({ requests });
80:       
81:       for (let j = 0; j < result.embeddings.length; j++) {
82:         vectorStore.push({ text: batchChunks[j], embedding: result.embeddings[j].values });
83:       }
84:       
85:       process.stdout.write(`Embedded ${Math.min(i + BATCH_SIZE, chunks.length)}/${chunks.length} chunks...\r`);
86:       
87:       // Small delay to prevent 429 Too Many Requests
88:       await new Promise(res => setTimeout(res, 500));
89:     } catch (error) {
90:       console.error(`\nFailed to embed batch ${i / BATCH_SIZE}: ${error.message}`);
91:     }
92:   }
93: 
94:   console.log(`\nFinished creating embeddings. Saving to cache...`);
95:   fs.writeFileSync(CACHE_FILE, JSON.stringify(vectorStore));
96: }
