98: /**
99:  * Retrieve the most relevant chunks for a given query
100:  */
101: async function retrieveRelevantContext(query, topK = 3) {
102:   if (vectorStore.length === 0 || !embeddingModel) return "";
103: 
104:   try {
105:     const result = await embeddingModel.embedContent(query);
106:     const queryEmbedding = result.embedding.values;
107: 
108:     // Calculate similarity for all chunks
109:     const scoredChunks = vectorStore.map(item => ({
110:       text: item.text,
111:       score: cosineSimilarity(queryEmbedding, item.embedding)
112:     }));
113: 
114:     // Sort descending by score
115:     scoredChunks.sort((a, b) => b.score - a.score);
116: 
117:     // Return topK chunks joined
118:     const topChunks = scoredChunks.slice(0, topK).map(c => c.text);
119:     return topChunks.join("\n\n...[SNIP]...\n\n");
120:   } catch (error) {
121:     console.error(`Retrieval error: ${error.message}`);
122:     return "";
123:   }
124: }
125: 
126: module.exports = {
127:   initializeRAG,
128:   retrieveRelevantContext
129: };
